// Built-in question bank: used when the AI is unavailable (no key, quota, network).
// Number questions are generated by code and their answers are computed by code (verify.js), same as everywhere else.
// The few multiple-choice questions are written by hand here (not by AI) and are tagged builtin:true.
function rng(seed) {
  let s = seed | 0;
  return () => { s = (s + 0x6D2B79F5) | 0; let t = Math.imul(s ^ (s >>> 15), 1 | s); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
const pick = (r, a, b) => a + Math.floor(r() * (b - a + 1));
const dec = (x) => String(parseFloat(x.toFixed(2)));
const frac = (r) => { const d = pick(r, 2, 9); return `${pick(r, 1, d - 1)}/${d}`; };

const GEN = {
  fracAdd: (r) => `${frac(r)}+${frac(r)}`,
  fracSub: (r) => { const a = frac(r), b = frac(r); const [an, ad] = a.split('/').map(Number), [bn, bd] = b.split('/').map(Number); return an / ad >= bn / bd ? `${a}-${b}` : `${b}-${a}`; },
  fracMul: (r) => `${frac(r)}*${frac(r)}`,
  fracDiv: (r) => `(${frac(r)})/(${frac(r)})`,
  intAdd: (r) => `${-pick(r, 2, 15)}+${pick(r, 2, 15)}`,
  intSub: (r) => `${pick(r, 2, 12)}-(-${pick(r, 2, 12)})`,
  intMul: (r) => `(-${pick(r, 2, 9)})*${pick(r, 2, 9)}`,
  decAdd: (r) => `${dec(pick(r, 1, 9) / 10 + pick(r, 1, 9) / 100)}+${dec(pick(r, 1, 9) / 10)}`,
  decSub: (r) => `${dec(pick(r, 5, 9) + pick(r, 1, 9) / 10)}-${dec(pick(r, 1, 4) + pick(r, 1, 9) / 10)}`,
  decMul: (r) => `${dec(pick(r, 1, 9) / 10)}*${pick(r, 2, 9)}`,
  pct: (r) => `${[10, 20, 25, 50, 75][pick(r, 0, 4)]}/100*${pick(r, 2, 12) * 20}`,
  power: (r) => `${pick(r, 2, 12)}^2`,
  cube: (r) => `${pick(r, 2, 6)}^3`,
  order: (r) => `${pick(r, 2, 9)}+${pick(r, 2, 9)}*${pick(r, 2, 9)}`,
  brackets: (r) => `(${pick(r, 5, 12)}-${pick(r, 1, 4)})*${pick(r, 2, 9)}`,
};

// topic keyword -> generators and hand-written concept questions (correct option is written first, shuffled later)
const TOPICS = [
  { name: 'Fractions', re: /fraction|numerator|denominator|tops? and bottoms?/i, gens: ['fracAdd', 'fracSub', 'fracMul', 'fracDiv'],
    narrow: [[/add|sum|plus/i, ['fracAdd']], [/subtract|minus|difference/i, ['fracSub']], [/multipl|times|product/i, ['fracMul']], [/divid|quotient/i, ['fracDiv']]],
    mcq: [['Which fraction is equal to 2/3?', ['4/6', '3/5', '2/6', '5/6']], ['What common denominator can you use to add 1/4 and 1/6?', ['12', '10', '5', '8']],
      ['Which is bigger, 3/4 or 2/3?', ['3/4', '2/3', 'They are equal', 'You cannot tell']], ['What is 6/8 in its simplest form?', ['3/4', '2/3', '6/8', '12/16']]] },
  { name: 'Integers', re: /integer|negative|positive|signed|number line/i, gens: ['intAdd', 'intSub', 'intMul'],
    mcq: [['Which is greater, \u22123 or \u22127?', ['\u22123', '\u22127', 'They are equal', 'You cannot tell']], ['Subtracting a negative number is the same as...', ['adding the matching positive number', 'subtracting the matching positive number', 'multiplying by zero', 'dividing by the number']],
      ['What is the sign of the product of two negative numbers?', ['Positive', 'Negative', 'Zero', 'It depends on the size']]] },
  { name: 'Decimals', re: /decimal/i, gens: ['decAdd', 'decSub', 'decMul'],
    mcq: [['Which is the largest: 0.5, 0.45, 0.405 or 0.054?', ['0.5', '0.45', '0.405', '0.054']], ['When you add decimals, line up the...', ['decimal points', 'last digits', 'first digits', 'zeros']],
      ['0.25 written as a fraction in simplest form is...', ['1/4', '2/5', '1/25', '25/10']]] },
  { name: 'Percentages', re: /percent|%/i, gens: ['pct'],
    mcq: [['50% of a number is the same as...', ['half of it', 'double it', 'a quarter of it', 'one tenth of it']], ['Which fraction is equal to 25%?', ['1/4', '1/5', '2/5', '1/2']], ['A quick way to find 10% of a number is to...', ['divide it by 10', 'multiply it by 10', 'subtract 10', 'add 10']]] },
  { name: 'Powers', re: /power|square|cube|exponent|index|indices/i, gens: ['power', 'cube'],
    mcq: [['What does 3^2 mean?', ['3 \u00d7 3', '3 + 3', '3 \u00d7 2', '2 \u00d7 2 \u00d7 2']], ['What is 2^3?', ['8', '6', '9', '5']]] },
  { name: 'Order of operations', re: /bodmas|pemdas|order of operation|brackets|operations/i, gens: ['order', 'brackets'],
    mcq: [['In 2 + 3 \u00d7 4, which part do you work out first?', ['3 \u00d7 4', '2 + 3', 'Either one', 'Neither']], ['What is the first step in 5 \u00d7 (2 + 3)?', ['Add 2 and 3 inside the brackets', 'Multiply 5 by 2', 'Multiply 5 by 3', 'Subtract']]] },
];

const topicNames = () => TOPICS.map((t) => t.name);
const findTopic = (text) => TOPICS.find((t) => t.re.test(String(text || '')));

// Returns raw questions (same shape the AI returns) or [] when the topic is not in the bank.
function build({ topic, count = 5, allowMcq = false, seed = Date.now() }) {
  const t = findTopic(topic);
  if (!t) return [];
  const r = rng(seed);
  let gens = t.gens;
  for (const [re, g] of t.narrow || []) if (re.test(topic)) { gens = g; break; }
  const nMcq = allowMcq ? Math.min(Math.floor(count / 3), t.mcq.length) : 0;
  const out = [], seen = new Set();
  let guard = 0;
  while (out.length < count - nMcq && guard++ < 200) {
    const e = GEN[gens[out.length % gens.length]](r);
    if (seen.has(e)) continue;
    seen.add(e); out.push({ type: 'calc', expression: e });
  }
  const pool = t.mcq.slice().sort(() => r() - 0.5).slice(0, nMcq);
  for (const [text, opts] of pool) {
    const order = opts.map((o, i) => [o, i]).sort(() => r() - 0.5);
    out.push({ type: 'mcq', text, options: order.map((x) => x[0]), correct: order.findIndex((x) => x[1] === 0), builtin: true });
  }
  return out;
}

module.exports = { build, topicNames, findTopic };
